#!/usr/bin/env python3
"""Rebuild the skill's generated files from the Matamba Gateway partner docs.

    python3 scripts/generate.py --docs PATH/TO/docs/partner           # write
    python3 scripts/generate.py --docs PATH/TO/docs/partner --check   # verify only
    python3 scripts/generate.py --repo-only --check                   # CI: no docs

The docs directory holds the partner pages (*.mdx), openapi.json and the
Postman files. Every file under references/, and each GENERATED block in the
SKILL.md files, comes from there. Nothing in them is typed by hand.

--check writes nothing. It exits 1 when:
  - a generated file or block differs from what the docs generate now (drift),
  - a docs page exists that the generator does not map (a new page),
  - a docs link in a hand-written file points at a page or anchor that
    doesn't exist,
  - the manifests disagree on the plugin's name, version or MCP address,
  - a SKILL.md breaks the Agent Skills naming or size rules,
  - the leak guard finds a forbidden term in any file or commit message.
--repo-only runs only the last three, for CI, which has no docs.
Exit 2 means the check could not run (bad arguments, unreadable docs, no
private term list for the leak guard). It is never a pass.

Standard library only, so it runs anywhere Python 3.9+ does.
"""
from __future__ import annotations

import argparse
import json
import re
import subprocess
import sys
from pathlib import Path

DOCS_BASE = "https://docs.matambaintelligence.com"
MCP_URL = f"{DOCS_BASE}/mcp"
PLUGIN_NAME = "matamba-gateway"

REPO = Path(__file__).resolve().parent.parent
PLUGIN = REPO / "plugins" / PLUGIN_NAME
SKILLS = PLUGIN / "skills"
MAIN_SKILL = SKILLS / PLUGIN_NAME
REFS = MAIN_SKILL / "references"
QUICKSTART_SKILL = SKILLS / "quickstart"

HEADER = (
    "<!-- Generated by scripts/generate.py from the Matamba Gateway partner docs. "
    "Do not edit: change the docs and run the script. -->"
)

# Each reference file is one or more whole docs pages, converted to Markdown.
REFERENCE_PAGES: dict[str, list[str]] = {
    "concepts.md": ["how-it-works", "versioning", "glossary"],
    "keys-and-security.md": ["keys-and-security"],
    "idempotency.md": ["idempotency"],
    "uncertain.md": ["handling-uncertain"],
    "errors.md": ["handle-errors", "errors", "troubleshooting"],
    "trading.md": ["trade", "orders"],
    "applications.md": ["applications"],
    "funding.md": ["funding", "wallet"],
    "webhooks.md": ["webhooks"],
    "limits.md": ["limits"],
    "sandbox.md": ["sandbox"],
    "support.md": ["support"],
}
QUICKSTART_PAGES = ["quickstart"]
# Pages deliberately left out, with the reason. Any other new page fails --check.
SKIPPED_PAGES = {
    "index": "the landing page: links only",
    "changelog": "only its newest section is used, in changelog.md",
}
# Files the docs serve besides pages, which hand-written files may link to.
STATIC_DOCS_FILES = {"openapi.json", "llms.txt", "llms-full.txt", "mcp",
                     "matamba-gateway.postman_collection.json",
                     "matamba-gateway.sandbox.postman_environment.json"}


class DocsError(Exception):
    """The docs could not be read or converted as expected."""


# ---------------------------------------------------------------- MDX pages

def slugify(text: str) -> str:
    """A heading's anchor, as the docs site builds it."""
    text = text.lower().replace("'", "").replace("’", "")
    return re.sub(r"[^a-z0-9]+", "-", text).strip("-")


class Page:
    def __init__(self, path: Path):
        self.slug = path.stem
        text = path.read_text(encoding="utf-8")
        m = re.match(r"^---\n(.*?)\n---\n", text, re.S)
        if not m:
            raise DocsError(f"{path.name}: no frontmatter")
        self.meta = {}
        for line in m.group(1).splitlines():
            key, _, value = line.partition(":")
            self.meta[key.strip()] = value.strip().strip('"')
        self.title = self.meta.get("title", self.slug)
        self.lines = text[m.end():].splitlines()
        self.anchors = set()
        fence = False
        for line in self.lines:
            if line.lstrip().startswith("```"):
                fence = not fence
                continue
            if fence:
                continue
            h = re.match(r"^(#{1,6})\s+(.*)$", line)
            if h:
                self.anchors.add(slugify(re.sub(r"[`*]", "", h.group(2))))
            for a in re.findall(r'<a id="([^"]+)"', line):
                self.anchors.add(a)

    def block(self, name: str) -> list[str]:
        start, end = f"[generated: {name}]: #", f"[end generated: {name}]: #"
        try:
            i, j = self.lines.index(start), self.lines.index(end)
        except ValueError:
            raise DocsError(f"{self.slug}.mdx: no generated block '{name}'")
        return self.lines[i + 1:j]

    def section(self, heading: str) -> list[str]:
        for i, line in enumerate(self.lines):
            h = re.match(r"^(#{1,6})\s+(.*)$", line)
            if h and h.group(2).strip() == heading:
                level = len(h.group(1))
                out = []
                for nxt in self.lines[i + 1:]:
                    h2 = re.match(r"^(#{1,6})\s", nxt)
                    if h2 and len(h2.group(1)) <= level:
                        break
                    out.append(nxt)
                return out
        raise DocsError(f"{self.slug}.mdx: no section '{heading}'")


def absolute_links(line: str, page_slug: str) -> str:
    line = re.sub(r"\]\((/[^)\s]*)\)", lambda m: f"]({DOCS_BASE}{m.group(1)})", line)
    return re.sub(r"\]\((#[^)\s]*)\)", lambda m: f"]({DOCS_BASE}/{page_slug}{m.group(1)})", line)


def to_markdown(lines: list[str], page_slug: str) -> list[str]:
    """Convert MDX body lines to plain Markdown. Unknown components fail."""
    out: list[str] = []
    fence = False
    callout = None
    for raw in lines:
        line = raw.rstrip()
        stripped = line.strip()
        if stripped.startswith("```"):
            fence = not fence
            out.append(("> " if callout else "") + line)
            continue
        if fence:
            out.append(("> " if callout else "") + line)
            continue
        if re.match(r"^\[(end )?generated: [a-z0-9-]+\]: #$", stripped):
            continue
        if re.match(r'^<a id="[^"]+"></a>$', stripped):
            continue
        if stripped in ("<CodeGroup>", "</CodeGroup>", "<Steps>", "</Steps>", "</Step>"):
            continue
        step = re.match(r'^<Step title="([^"]+)">$', stripped)
        if step:
            out.append(f"**{step.group(1)}**")
            out.append("")
            continue
        box = re.match(r"^<(Note|Warning|Tip|Info)>$", stripped)
        if box:
            callout = box.group(1)
            out.append(f"> **{callout}.**")
            continue
        if callout and stripped == f"</{callout}>":
            callout = None
            continue
        if re.match(r"^</?[A-Za-z]", stripped):
            raise DocsError(f"{page_slug}.mdx: unhandled component: {stripped[:60]}")
        line = absolute_links(line, page_slug)
        out.append(("> " + line if line else ">") if callout else line)
    if fence or callout:
        raise DocsError(f"{page_slug}.mdx: unclosed code fence or callout")
    squeezed: list[str] = []
    for line in out:
        if line == "" and squeezed and squeezed[-1] == "":
            continue
        squeezed.append(line)
    while squeezed and squeezed[0] == "":
        squeezed.pop(0)
    while squeezed and squeezed[-1] == "":
        squeezed.pop()
    return squeezed


def page_markdown(page: Page, level: int = 1) -> list[str]:
    """A whole page, its headings pushed down so the file keeps one H1."""
    body = []
    fence = False
    for line in to_markdown(page.lines, page.slug):
        if line.lstrip("> ").startswith("```"):
            fence = not fence
        if not fence and re.match(r"^#{1,5}\s", line):
            line = "#" * (level - 1) + line
        body.append(line)
    head = "#" * level
    url = f"{DOCS_BASE}/{page.slug}"
    return [f"{head} {page.title}", "", f"Source: <{url}>", "", *body]


# ---------------------------------------------------------------- OpenAPI

def api_reference_url(op: dict) -> str:
    return f"{DOCS_BASE}/api-reference/{slugify(op['tags'][0])}/{slugify(op['summary'])}"


def literal(value) -> str:
    return f"`{value}`" if isinstance(value, str) else f"`{json.dumps(value)}`"


def describe(prop: dict, spec: dict) -> str:
    """A property's description, or its referenced schema's when it has none."""
    if prop.get("description"):
        return prop["description"]
    if "$ref" in prop:
        return spec["components"]["schemas"].get(prop["$ref"].split("/")[-1], {}).get("description", "")
    return ""


def collapse(text: str) -> str:
    text = re.sub(r"\s+", " ", text or "").strip()
    text = re.sub(r"\]\((/[^)\s]*)\)", lambda m: f"]({DOCS_BASE}{m.group(1)})", text)
    return text.replace("|", "\\|")


def type_of(schema: dict, spec: dict) -> str:
    if "$ref" in schema:
        name = schema["$ref"].split("/")[-1]
        target = spec["components"]["schemas"].get(name, {})
        if "enum" in target:
            return name + " (" + ", ".join(literal(v) for v in target["enum"]) + ")"
        rule = type_of(target, spec) if target.get("type") else "object"
        return f"{name}: {rule}"
    parts = []
    t = schema.get("type")
    if isinstance(t, list):
        t = " or ".join(t)
    if t:
        parts.append(t)
    if "format" in schema:
        parts.append(schema["format"])
    if "enum" in schema:
        parts.append("one of " + ", ".join(literal(v) for v in schema["enum"]))
    if "const" in schema:
        parts.append(f"always `{schema['const']}`")
    if "pattern" in schema:
        parts.append(f"pattern `{schema['pattern']}`")
    for key, word in (("minLength", "min length"), ("maxLength", "max length"),
                      ("minimum", "min"), ("maximum", "max")):
        if key in schema:
            parts.append(f"{word} {schema[key]}")
    return ", ".join(parts) or "any"


def schema_table(name: str, spec: dict) -> list[str]:
    schema = spec["components"]["schemas"][name]
    required = set(schema.get("required", []))
    rows = [f"`{name}`. {collapse(schema.get('description', ''))}", "",
            "| Field | Required | Type and rule | Description |", "|---|---|---|---|"]
    for field, prop in schema.get("properties", {}).items():
        rows.append(f"| `{field}` | {'Yes' if field in required else 'No'} | "
                    f"{collapse(type_of(prop, spec))} | {collapse(describe(prop, spec))} |")
    return rows


def endpoints_markdown(spec: dict) -> list[str]:
    params = spec["components"].get("parameters", {})
    server = spec["servers"][0]["url"]
    out = ["# Endpoint index", "",
           f"Source: <{DOCS_BASE}/openapi.json>, the API reference.", "",
           f"Every path is under `/v1`. The API reference's server is the sandbox, `{server}`. "
           "The live host comes with your live keys: never guess it.", "",
           "| Method | Path | What it does | Key scope | `Idempotency-Key` | Reference |",
           "|---|---|---|---|---|---|"]
    ops = []
    for path, item in spec["paths"].items():
        for method, op in item.items():
            if method in ("get", "post", "put", "delete", "patch"):
                ops.append((path, method, op))
    for path, method, op in ops:
        sec = op.get("security")
        scopes = ", ".join(s for req in (sec or []) for s in req.get("bearer", []))
        scope = f"`{scopes}`" if scopes else "Any key"
        idem = any(p.get("$ref", "").endswith("/IdempotencyKeyParameter") for p in op.get("parameters", []))
        out.append(f"| `{method.upper()}` | `{path}` | {collapse(op.get('summary', ''))} | {scope} | "
                   f"{'Required' if idem else 'Not used'} | [{op['operationId']}]({api_reference_url(op)}) |")
    out += ["", "## What each endpoint does", ""]
    for path, method, op in ops:
        out += [f"### `{method.upper()} {path}`", "", collapse(op.get("description", "")), ""]
        query = []
        for p in op.get("parameters", []) + spec["paths"][path].get("parameters", []):
            if "$ref" in p:
                p = params[p["$ref"].split("/")[-1]]
            query.append(f"- `{p['name']}` ({p['in']}{', required' if p.get('required') else ''}): "
                         f"{collapse(type_of(p.get('schema', {}), spec))}. {collapse(p.get('description', ''))}")
        if query:
            out += ["Parameters:", "", *query, ""]
        body = op.get("requestBody")
        if body:
            content = body.get("content", {})
            for ctype, media in content.items():
                ref = media.get("schema", {}).get("$ref")
                target = ref.split("/")[-1] if ref else type_of(media.get("schema", {}), spec)
                out.append(f"Body: `{ctype}`, {target}.")
            out.append("")
        statuses = [s for s in op.get("responses", {}) if s != "default"]
        out += [f"Responses: {', '.join(f'`{s}`' for s in statuses)}, and `default` (the shared error shape).", ""]
    out += ["## Request bodies", ""]
    for name in ("OrderRequest", "ApplicationRequest", "AllocationRequest"):
        out += [f"### {name}", "", *schema_table(name, spec), ""]
    out += ["## Money fields", "",
            "Every field whose name ends `_kobo` is an integer in kobo. Every field ending "
            "`_kobo_decimal` is a decimal string of kobo: parse it with a decimal type, never a float.", "",
            "| Object | Field | Description |", "|---|---|---|"]
    for name, schema in spec["components"]["schemas"].items():
        for field, prop in schema.get("properties", {}).items():
            if field.endswith("_kobo") or field.endswith("_kobo_decimal"):
                out.append(f"| `{name}` | `{field}` | {collapse(describe(prop, spec))} |")
    out += ["", "## Values", "",
            "New values can be added to any of these lists. Treat one you don't recognise with a safe default.", "",
            "| List | Values |", "|---|---|"]
    seen = set()
    for name, schema in spec["components"]["schemas"].items():
        cands = [(name, schema)] + [(p.get("title") or f"{name}.{f}", p)
                                    for f, p in schema.get("properties", {}).items()]
        for label, s in cands:
            if "enum" in s and label not in seen:
                seen.add(label)
                out.append(f"| `{label}` | {', '.join(literal(v) for v in s['enum'])} |")
    return out


# ---------------------------------------------------------------- generation

class Docs:
    def __init__(self, root: Path):
        if not (root / "openapi.json").is_file():
            raise DocsError(f"{root}: no openapi.json here. Pass the docs/partner directory.")
        self.root = root
        self.pages = {p.stem: Page(p) for p in sorted(root.glob("*.mdx"))}
        self.spec = json.loads((root / "openapi.json").read_text(encoding="utf-8"))

    def page(self, slug: str) -> Page:
        if slug not in self.pages:
            raise DocsError(f"no page {slug}.mdx")
        return self.pages[slug]

    def unmapped_pages(self) -> list[str]:
        mapped = {s for pages in REFERENCE_PAGES.values() for s in pages} | set(QUICKSTART_PAGES) | set(SKIPPED_PAGES)
        return sorted(set(self.pages) - mapped)

    def release(self) -> str:
        for line in self.page("changelog").lines:
            m = re.match(r"^## (.+)$", line)
            if m:
                return m.group(1).strip()
        raise DocsError("changelog.mdx: no release heading")

    def sandbox_host(self) -> str:
        urls = re.findall(r"https://[a-z0-9.-]+", "\n".join(self.page("quickstart").block("sandbox-address")))
        server = self.spec["servers"][0]["url"]
        if len(set(urls)) != 1 or urls[0] != server:
            raise DocsError(f"sandbox host: quickstart says {sorted(set(urls))}, openapi.json says {server}")
        return server


def build_files(docs: Docs) -> dict[Path, str]:
    files: dict[Path, str] = {}
    for name, slugs in REFERENCE_PAGES.items():
        lines = [HEADER, ""]
        if len(slugs) == 1:
            lines += page_markdown(docs.page(slugs[0]), level=1)
        else:
            titles = " / ".join(docs.page(s).title for s in slugs)
            lines += [f"# {titles}", ""]
            for s in slugs:
                lines += page_markdown(docs.page(s), level=2) + [""]
        files[REFS / name] = "\n".join(lines).rstrip() + "\n"
    changelog = docs.page("changelog")
    release = docs.release()
    lines = [HEADER, "", "# Changelog: the newest release", "",
             f"Source: <{DOCS_BASE}/changelog>", "", f"## {release}", "",
             *to_markdown(changelog.section(release), "changelog")]
    files[REFS / "changelog.md"] = "\n".join(lines).rstrip() + "\n"
    files[REFS / "endpoints.md"] = "\n".join([HEADER, "", *endpoints_markdown(docs.spec)]).rstrip() + "\n"
    qs = [HEADER, "", *page_markdown(docs.page("quickstart"), level=1)]
    files[QUICKSTART_SKILL / "references" / "quickstart.md"] = "\n".join(qs).rstrip() + "\n"
    return files


def build_blocks(docs: Docs) -> dict[str, str]:
    """Content for each GENERATED block inside a hand-written SKILL.md."""
    idem = to_markdown(docs.page("idempotency").section("Which requests need a key"), "idempotency")
    limits = to_markdown(docs.page("limits").block("limits"), "limits")
    responses = to_markdown(docs.page("limits").block("limit-responses"), "limits")
    app = docs.spec["components"]["schemas"]["ApplicationRequest"]
    required = [f for f in app["properties"] if f in set(app.get("required", []))]
    optional = [f for f in app["properties"] if f not in set(app.get("required", []))]
    return {
        "application-fields": "- Required fields: " + ", ".join(f"`{f}`" for f in required) + ".\n"
                              "- Optional fields: " + ", ".join(f"`{f}`" for f in optional) + ".",
        "release": f"Docs release: **{docs.release()}** (the newest heading in the "
                   f"[changelog]({DOCS_BASE}/changelog)).",
        "sandbox-host": f"Sandbox: `{docs.sandbox_host()}`",
        "idempotency-required": "\n".join(idem),
        "limits": "\n".join(limits + [""] + responses),
    }


BLOCK_RE = re.compile(r"^([ \t]*)<!-- BEGIN GENERATED: ([a-z-]+) -->\n.*?^[ \t]*<!-- END GENERATED: \2 -->$",
                      re.S | re.M)


def fill_blocks(text: str, blocks: dict[str, str], where: str, problems: list[str]) -> str:
    """Replace each block's body, indented like its BEGIN marker."""
    def swap(m: re.Match) -> str:
        indent, name = m.group(1), m.group(2)
        if name not in blocks:
            problems.append(f"{where}: unknown GENERATED block '{name}'")
            return m.group(0)
        body = "\n".join((indent + line) if line else "" for line in blocks[name].splitlines())
        return (f"{indent}<!-- BEGIN GENERATED: {name} -->\n{body}\n"
                f"{indent}<!-- END GENERATED: {name} -->")
    return BLOCK_RE.sub(swap, text)


def skill_files() -> list[Path]:
    return sorted(SKILLS.glob("*/SKILL.md"))


# ---------------------------------------------------------------- checks

def check_links(docs: Docs, files: list[Path], problems: list[str]) -> None:
    api_pages = {api_reference_url(op)[len(DOCS_BASE) + 1:]
                 for item in docs.spec["paths"].values() for m, op in item.items()
                 if m in ("get", "post", "put", "delete", "patch")}
    for path in files:
        text = path.read_text(encoding="utf-8")
        for url in re.findall(re.escape(DOCS_BASE) + r"(/[^\s)>`\"'\]]*)?", text):
            url = url.rstrip(".,;:")
            target = url.lstrip("/")
            page, _, anchor = target.partition("#")
            page = page.rstrip("/")
            if page.endswith(".md"):
                page = page[:-3]
            if page in ("", *STATIC_DOCS_FILES) or page in api_pages:
                if anchor:
                    problems.append(f"{path.relative_to(REPO)}: anchor on a non-page link {url}")
                continue
            if page not in docs.pages:
                problems.append(f"{path.relative_to(REPO)}: no docs page for {DOCS_BASE}{url}")
            elif anchor and anchor not in docs.pages[page].anchors:
                problems.append(f"{path.relative_to(REPO)}: no anchor #{anchor} on {DOCS_BASE}/{page}")


def docs_internal_link_warnings(docs: Docs) -> list[str]:
    """Links inside the docs themselves that don't resolve. Reported, never fatal."""
    warnings = []
    for page in docs.pages.values():
        for n, line in enumerate(page.lines, start=1):
            for target in re.findall(r"\]\((/[^)\s]*|#[^)\s]*)\)", line):
                slug, _, anchor = (target if target.startswith("/") else f"/{page.slug}{target}")[1:].partition("#")
                if slug in STATIC_DOCS_FILES or slug.startswith("api-reference/"):
                    continue
                if slug not in docs.pages:
                    warnings.append(f"{page.slug}.mdx: link to missing page /{slug}")
                elif anchor and anchor not in docs.pages[slug].anchors:
                    warnings.append(f"{page.slug}.mdx: link to missing anchor /{slug}#{anchor}")
    return sorted(set(warnings))


def frontmatter(path: Path) -> dict[str, str]:
    text = path.read_text(encoding="utf-8")
    m = re.match(r"^---\n(.*?)\n---\n", text, re.S)
    if not m:
        return {}
    out = {}
    for line in m.group(1).splitlines():
        if line[:1] not in (" ", "\t") and ":" in line:
            key, _, value = line.partition(":")
            out[key.strip()] = value.strip()
    return out


def check_skills(problems: list[str]) -> None:
    for path in skill_files():
        rel = path.relative_to(REPO)
        fm = frontmatter(path)
        name, desc = fm.get("name", ""), fm.get("description", "")
        if name != path.parent.name:
            problems.append(f"{rel}: name '{name}' must match its directory '{path.parent.name}'")
        if not re.fullmatch(r"[a-z0-9]+(-[a-z0-9]+)*", name) or len(name) > 64:
            problems.append(f"{rel}: name '{name}' breaks the Agent Skills name rules")
        if not 1 <= len(desc) <= 1024:
            problems.append(f"{rel}: description is {len(desc)} characters; the standard allows 1 to 1024")
        lines = path.read_text(encoding="utf-8").count("\n")
        if lines > 500:
            problems.append(f"{rel}: {lines} lines; keep SKILL.md under 500")


def load_json(path: Path, problems: list[str]) -> dict:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as err:
        problems.append(f"{path.relative_to(REPO)}: {err}")
        return {}


def check_manifests(problems: list[str]) -> None:
    claude = load_json(PLUGIN / ".claude-plugin" / "plugin.json", problems)
    portable = load_json(PLUGIN / "plugin.json", problems)
    claude_mkt = load_json(REPO / ".claude-plugin" / "marketplace.json", problems)
    agents_mkt = load_json(REPO / ".agents" / "plugins" / "marketplace.json", problems)
    claude_mcp = load_json(PLUGIN / ".mcp.json", problems)
    portable_mcp = load_json(PLUGIN / "mcp.json", problems)
    for label, man in (("plugin.json", portable), (".claude-plugin/plugin.json", claude)):
        if man.get("name") != PLUGIN_NAME:
            problems.append(f"{label}: name is {man.get('name')!r}, expected {PLUGIN_NAME!r}")
    if claude.get("version") != portable.get("version"):
        problems.append(f"versions differ: .claude-plugin/plugin.json {claude.get('version')!r}, "
                        f"plugin.json {portable.get('version')!r}")
    for label, mkt in ((".claude-plugin/marketplace.json", claude_mkt),
                       (".agents/plugins/marketplace.json", agents_mkt)):
        entries = [p for p in mkt.get("plugins", []) if p.get("name") == PLUGIN_NAME]
        if len(entries) != 1:
            problems.append(f"{label}: expected one entry named {PLUGIN_NAME}")
            continue
        src = entries[0].get("source")
        rel = src.get("path") if isinstance(src, dict) else src
        if not rel or (REPO / rel).resolve() != PLUGIN.resolve():
            problems.append(f"{label}: source {src!r} does not point at plugins/{PLUGIN_NAME}")
    for label, cfg in ((".mcp.json", claude_mcp), ("mcp.json", portable_mcp)):
        urls = [s.get("url") for s in cfg.get("mcpServers", {}).values()]
        if urls != [MCP_URL]:
            problems.append(f"{label}: MCP servers {urls}, expected [{MCP_URL}]")
    openai_yaml = MAIN_SKILL / "agents" / "openai.yaml"
    if not openai_yaml.is_file() or MCP_URL not in openai_yaml.read_text(encoding="utf-8"):
        problems.append(f"{openai_yaml.relative_to(REPO)}: missing, or does not name {MCP_URL}")


# The leak guard. Terms that name or hint at the system behind the gateway must
# never appear anywhere in this public repo, so the list is not in it in any
# form: not the terms, not their hashes (short terms hashed are found again by
# guessing, 1 Oct 2026). The maintainer keeps it in a private file outside the
# repo, one "kind term" per line, lowercase:
#   substring: anywhere inside a word,
#   word:      a whole word, split on anything but letters and digits,
#   prefix:    the start of a word, or the part after an underscore.
# Without that file the check could not run, which is never a pass.
LEAK_TERMS_DEFAULT = Path.home() / ".matamba-gateway-kit" / "leak-terms"
_CANARY = "zzleak" + "canaryzz"


def read_leak_terms(path: Path) -> dict[str, set[str]]:
    terms: dict[str, set[str]] = {"substring": set(), "word": set(), "prefix": set()}
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        kind, _, term = line.partition(" ")
        if kind not in terms or not term.strip():
            raise ValueError(f"{path}: cannot read the line {line!r}")
        terms[kind].add(term.strip().lower())
    if not any(terms.values()):
        raise ValueError(f"{path}: holds no terms")
    terms["substring"].add(_CANARY)
    return terms


def leak_hits(text: str, terms: dict[str, set[str]]) -> int:
    hits = 0
    for token in re.findall(r"[a-z0-9_]+", text.lower()):
        for word in token.replace("_", " ").split():
            hits += word in terms["word"]
            hits += sum(word.count(t) for t in terms["substring"])
        starts = [0] + [i + 1 for i, ch in enumerate(token) if ch == "_"]
        hits += sum(token.startswith(t, s) for s in starts for t in terms["prefix"])
    return hits


def check_leaks(problems: list[str], docs_root: Path | None, terms: dict[str, set[str]]) -> None:
    if leak_hits(f"a {_CANARY} b", terms) != 1:
        problems.append("leak guard: the self-test canary was not found; the guard is broken")
        return
    try:
        listed = subprocess.run(["git", "-C", str(REPO), "ls-files", "-z", "--cached", "--others",
                                 "--exclude-standard"], capture_output=True, check=True).stdout
        messages = subprocess.run(["git", "-C", str(REPO), "log", "--format=%H%n%B"],
                                  capture_output=True, text=True).stdout
    except (OSError, subprocess.CalledProcessError) as err:
        problems.append(f"leak guard: could not list the repo's files: {err}")
        return
    for rel in filter(None, listed.decode().split("\0")):
        path = REPO / rel
        if not path.is_file():
            continue
        data = path.read_bytes()
        if b"\0" in data:
            continue
        n = leak_hits(data.decode("utf-8", errors="replace"), terms) + leak_hits(rel, terms)
        if n:
            problems.append(f"leak guard: {n} forbidden term(s) in {rel}")
    if leak_hits(messages, terms):
        problems.append("leak guard: forbidden term(s) in a commit message")
    if docs_root is not None:
        for path in sorted(docs_root.glob("*")):
            if path.is_file() and path.suffix in (".mdx", ".json") and leak_hits(path.read_text(encoding="utf-8"), terms):
                problems.append(f"leak guard: forbidden term(s) in the docs source {path.name}")


# ---------------------------------------------------------------- main

def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--docs", type=Path, help="the gateway's docs/partner directory")
    ap.add_argument("--repo-only", action="store_true",
                    help="with --check, without docs: the skill rules, the manifests and the leak guard (CI)")
    ap.add_argument("--check", action="store_true", help="verify only; write nothing")
    ap.add_argument("--leak-terms", type=Path, default=LEAK_TERMS_DEFAULT,
                    help=f"the private list of terms the leak guard looks for (default {LEAK_TERMS_DEFAULT})")
    args = ap.parse_args()
    try:
        terms = read_leak_terms(args.leak_terms)
    except (OSError, ValueError) as err:
        print(f"generate.py: the leak guard could not run: {err}", file=sys.stderr)
        return 2
    if args.repo_only:
        if not args.check or args.docs is not None:
            print("generate.py: --repo-only goes with --check and without --docs", file=sys.stderr)
            return 2
        problems: list[str] = []
        check_skills(problems)
        check_manifests(problems)
        check_leaks(problems, None, terms)
        for problem in problems:
            print(f"FAIL {problem}", file=sys.stderr)
        if problems:
            print(f"generate.py: {len(problems)} problem(s)", file=sys.stderr)
            return 1
        print("generate.py: ok (repo only: skill rules, manifests, leak guard).")
        return 0
    if args.docs is None:
        print("generate.py: --docs is required (or --repo-only with --check)", file=sys.stderr)
        return 2
    try:
        docs = Docs(args.docs.resolve())
        files = build_files(docs)
        blocks = build_blocks(docs)
    except (DocsError, OSError, ValueError, KeyError) as err:
        print(f"generate.py: could not read the docs: {err}", file=sys.stderr)
        return 2

    problems: list[str] = []
    for slug in docs.unmapped_pages():
        problems.append(f"new docs page {slug}.mdx is not mapped: add it to REFERENCE_PAGES or SKIPPED_PAGES")

    changed = []
    for path, content in files.items():
        current = path.read_text(encoding="utf-8") if path.is_file() else None
        if current != content:
            changed.append(path)
            if not args.check:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding="utf-8")
    stale = sorted(set(REFS.glob("*.md")) - set(files))
    for path in stale:
        problems.append(f"{path.relative_to(REPO)}: not generated from any docs page; delete it")
    for path in skill_files():
        text = path.read_text(encoding="utf-8")
        filled = fill_blocks(text, blocks, str(path.relative_to(REPO)), problems)
        if filled != text:
            changed.append(path)
            if not args.check:
                path.write_text(filled, encoding="utf-8")

    if args.check:
        for path in changed:
            problems.append(f"drift: {path.relative_to(REPO)} differs from what the docs generate")
    else:
        for path in changed:
            print(f"wrote {path.relative_to(REPO)}")

    hand_written = [*skill_files(), REPO / "README.md"]
    check_links(docs, [p for p in hand_written if p.is_file()], problems)
    check_skills(problems)
    check_manifests(problems)
    check_leaks(problems, docs.root, terms)

    for warning in docs_internal_link_warnings(docs):
        print(f"docs warning: {warning}", file=sys.stderr)
    for problem in problems:
        print(f"FAIL {problem}", file=sys.stderr)
    if problems:
        print(f"generate.py: {len(problems)} problem(s)", file=sys.stderr)
        return 1
    print(f"generate.py: ok. {len(files)} generated files and {len(blocks)} blocks match "
          f"docs release '{docs.release()}'.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
